require_once __DIR__.'/includes/functions.php'; require_once __DIR__.'/includes/csrf.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';$location=trim($_POST['location']??'');$lat=$_POST['latitude']!==''?$_POST['latitude']:null;$lng=$_POST['longitude']!==''?$_POST['longitude']:null;try{if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8)throw new RuntimeException('Use a valid name/email and a password of at least 8 characters.');$s=db()->prepare('INSERT INTO users(name,email,password_hash,role,location,latitude,longitude) VALUES(?,?,?,\'user\',?,?,?)');$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$location,$lat,$lng]);session_regenerate_id(true);$_SESSION['user_id']=(int)db()->lastInsertId();flash('success','Welcome to RADIUS.');redirect('/');}catch(PDOException $e){flash('error',$e->getCode()==='23000'?'That email is already registered.':'Registration failed.');}catch(RuntimeException $e){flash('error',$e->getMessage());}}
$pageTitle='Register';include __DIR__.'/includes/header.php';?><form class="form-card" method="post"><h1>Create your RADIUS account</h1><p class="muted">One account can buy and sell.</p><?=csrf_field()?><div class="form-grid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Password</label><input type="password" name="password" minlength="8" required></div><div class="field"><label>Location</label><input name="location" placeholder="Badda, Dhaka"></div><div class="field"><label>Latitude</label><input name="latitude" inputmode="decimal"></div><div class="field"><label>Longitude</label><input name="longitude" inputmode="decimal"></div></div><div class="actions"><button type="button" class="btn btn-light" data-use-location>Use my location</button><button class="btn">Create account</button></div></form><?php include __DIR__.'/includes/footer.php';?>